SourceCode.Declaration:
/// <summary>
/// What HSMobileOpsLicense::verify() found - never thrown, always returned, so
/// HSMobileOpsUserService::signIn() can branch on it exactly the way it already branches on every
/// other sign-in condition (invalid credentials, locked out, no warehouse, ...).
///
/// Not a [DataContract] - this never crosses the wire on its own. signIn() reads it and re-expresses
/// whatever it found as an ErrorCode/Message on HSMobileOpsSignInResponse, the same contract every
/// other failure already uses.
///
/// `final`, `[Wrappable(false)]` and `internal` for the same reason as HSMobileOpsLicense itself -
/// a Chain of Command extension on parmValid() that always returned true would bypass the license
/// check just as completely as one on verify() would, regardless of how strong the signature check
/// upstream is; `internal` also means no package outside this model can even see this class to try.
/// </summary>
[Wrappable(false)]
internal final class HSMobileOpsLicenseStatus
{
    boolean valid;
    str     errorCode;
    str     message;
    int     maxDevices;
    str     expiryUtc;
    str     customerId;
    str     tenantId;
    int     daysUntilExpiry;
    str     integrityVerdict;

}

Method.Source:
internal boolean parmValid(boolean _value = valid)
{
    valid = _value;
    return valid;
}

/// <summary>
/// NO_LICENSE, LICENSE_INVALID, LICENSE_EXPIRED, LICENSE_REVOKED or INTEGRITY_FAILED. Blank
/// when valid is true. The last two are only ever set by
/// HSMobileOpsLicense::verifyWithAttestation, after the local certificate/license chain
/// below has already passed - see that method's doc comment.
/// </summary>
internal str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

internal str parmMessage(str _value = message)
{
    message = _value;
    return message;
}

/// <summary>
/// The device cap encoded in the key. Meaningful even when the key is expired - a supervisor
/// looking at the license form still wants to know what the old key granted.
/// </summary>
internal int parmMaxDevices(int _value = maxDevices)
{
    maxDevices = _value;
    return maxDevices;
}

/// <summary>
/// The expiry date exactly as encoded in the key (ISO 8601 UTC text). Kept as text rather than
/// an X++ utcdatetime - the only comparison that matters (is it in the past) already happened
/// in .NET inside verify(), and text round-trips into a display or a log line without any
/// further conversion.
/// </summary>
internal str parmExpiryUtc(str _value = expiryUtc)
{
    expiryUtc = _value;
    return expiryUtc;
}

internal str parmCustomerId(str _value = customerId)
{
    customerId = _value;
    return customerId;
}

/// <summary>
/// The vendor-assigned opaque tenant/environment id the license was issued for - lets a
/// license/certificate pair minted for one D365FO environment be rejected if pasted into a
/// different one. See HSMobileOpsLicense::verify()'s "Step 3" check.
/// </summary>
internal str parmTenantId(str _value = tenantId)
{
    tenantId = _value;
    return tenantId;
}

/// <summary>
/// How many whole days remain until expiryUtc - only meaningful (and only set) when valid is
/// true. Drives the "renew soon" warning signIn() attaches to an otherwise-successful sign-in;
/// see HSMobileOpsUserService::signIn.
/// </summary>
internal int parmDaysUntilExpiry(int _value = daysUntilExpiry)
{
    daysUntilExpiry = _value;
    return daysUntilExpiry;
}

/// <summary>
/// PASS / FAIL / UNVERIFIED from the cloud check's Play Integrity evaluation, or blank when
/// verify() alone was called (verifyWithAttestation never ran). Informational - errorCode is
/// what callers branch on; this is here so a support conversation or a log line can say why
/// INTEGRITY_FAILED happened without re-deriving it.
/// </summary>
internal str parmIntegrityVerdict(str _value = integrityVerdict)
{
    integrityVerdict = _value;
    return integrityVerdict;
}
